    summary.published > 0 ||
    post.variants.some((v) => v.publishState === "PUBLISHED");
  const updated = await prisma.post.update({
    where: { id: postId },
    data: hadPublishedVariant ? { publishedAt: now, status: "PUBLISHED" } : {},
    include: POST_INCLUDE,
  });

  return { post: updated, summary };
}

