  return prisma.post.findMany({
    where: {
      workspaceId,
      OR: [
        { status: "SCHEDULED", scheduledAt: { gte: start, lt: end } },
        { status: "PUBLISHED", publishedAt: { gte: start, lt: end } },
      ],
    },
    include: POST_INCLUDE,
    orderBy: [{ status: "desc" }, { scheduledAt: "asc" }],
  });
