import { defineConfig } from "vitest/config";
import path from "node:path";

export default defineConfig({
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "src"),
    },
  },
  test: {
    setupFiles: ["./tests/vitest-setup.ts"],
    // Unit tests in src/ run without a database; tests/integration/* resets the
    // TEST database schema in its own beforeAll.
    include: ["src/**/*.test.ts", "tests/**/*.test.ts"],
  },
});
// Loads .env before any test file is imported (needed by @/lib/db singleton).
import "dotenv/config";
// Embedded Hono API (ADR-0010) mounted on the Next.js catch-all route.
import { getToken } from "next-auth/jwt";
import { createApiApp } from "@/server/http";
import { prisma } from "@/lib/db";

const app = createApiApp({
  prisma,
  getAccountId: async (c) => {
    // getToken only reads the cookie header — pass headers directly (no
    // NextRequest wrapping; Hono hands us a plain Request here).
    const token = await getToken({
      req: { headers: c.req.raw.headers } as never,
      secret: process.env.AUTH_SECRET,
    });
    return token?.sub ?? null;
  },
});

export const GET = (req: Request) => app.fetch(req);
export const POST = (req: Request) => app.fetch(req);
export const PATCH = (req: Request) => app.fetch(req);
export const DELETE = (req: Request) => app.fetch(req);
import { handlers } from "@/lib/auth";

export const { GET, POST } = handlers;
// Unified API error — services throw it; the Hono onError handler renders it.
export class ApiError extends Error {
  readonly status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}
// Composer state (Zustand) — local editor state only.
// Server persistence lives in TanStack Query (see Composer.tsx).
import { create } from "zustand";

export interface ComposerChannel {
  slug: string;
  name: string;
  connected: boolean;
}

interface ComposerState {
  globalDraft: string;
  /** Per-channel overrides — a channel is "touched" once the user edits it. */
  variants: Record<string, string>;
  touched: Record<string, boolean>;
  activeTab: string | null;
  setGlobalDraft: (text: string) => void;
  setVariant: (slug: string, content: string) => void;
  setActiveTab: (slug: string | null) => void;
  /** Effective content for a channel: override if touched, else the global draft. */
  contentFor: (slug: string) => string;
  reset: () => void;
}

export const useComposerStore = create<ComposerState>((set, get) => ({
  globalDraft: "",
  variants: {},
  touched: {},
  activeTab: null,
  setGlobalDraft: (text) => set({ globalDraft: text }),
  setVariant: (slug, content) =>
    set((s) => ({ variants: { ...s.variants, [slug]: content }, touched: { ...s.touched, [slug]: true } })),
  setActiveTab: (slug) => set({ activeTab: slug }),
  contentFor: (slug) =>
    get().touched[slug] ? get().variants[slug] ?? "" : get().globalDraft,
  reset: () => set({ globalDraft: "", variants: {}, touched: {}, activeTab: null }),
}));
"use client";

import { useState } from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";

export function Providers({ children }: { children: React.ReactNode }) {
  const [client] = useState(
    () =>
      new QueryClient({
        defaultOptions: { queries: { staleTime: 30_000, retry: 1 } },
      }),
  );
  return <QueryClientProvider client={client}>{children}</QueryClientProvider>;
}

